import { Group, PlaneGeometry, Mesh, MeshBasicNodeMaterial, DoubleSide, Color } from 'three/webgpu';
import { uv, vec3, mix, texture, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
    // --- Gather text content ---
    const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

    // --- Create root group with scene placement ---
    const group = new Group();
    group.position.set(0, 1, 0.06);
    group.scale.set(1, 1, 1);
    group.rotation.set(0, 0, 0);

    // --- Plane geometry matching atlas region aspect ratio (512x320 ~ 1.6:1) ---
    const width = 1.6;
    const height = 1.0;
    const geo = new PlaneGeometry(width, height);

    // --- Design tokens ---
    const surfaceColor = new Color('#0b0b10');
    const inkColor = new Color('#16161d');
    const paperColor = new Color('#e8ecf2');

    // --- TSL nodes for engineered gradient surface with subtle grain ---
    const uvNode = uv();
    const texUniform = uniform(null); // grain texture placeholder

    // Vertical gradient from surface (bottom) to ink (top)
    const gradientNode = mix(
        vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b),
        vec3(inkColor.r, inkColor.g, inkColor.b),
        uvNode.y
    );

    // Subtle grain overlay
    const grainStrength = float(0.15);
    const texNode = texture(texUniform, uvNode);
    const finalColor = mix(gradientNode, texNode.rgb, grainStrength);

    // --- Material (unlit, static composition) ---
    const mat = new MeshBasicNodeMaterial({
        transparent: false,
        side: DoubleSide,
        outputNode: vec4(finalColor, 1.0)
    });

    const mesh = new Mesh(geo, mat);
    group.add(mesh);

    // --- Load grain texture asynchronously ---
    if (config.imageUrl) {
        ctx.textureLoader.loadTexture(config.imageUrl).then((loadedTex) => {
            texUniform.value = loadedTex;
            mat.needsUpdate = true;
        });
    }

    // --- Render text content "Pricing 2" via font atlas ---
    let textMesh = null;
    const textItem = items.find(item => item.text && item.role === 'headline');
    if (textItem) {
        const fontSize = textItem.typography?.fontSize || 39;
        textMesh = ctx.fontAtlas.createText(textItem.text, {
            fontSize: fontSize,
            color: paperColor.getHexString(),
            align: 'center'
        });
        if (textMesh) {
            textMesh.position.set(0, 0, 0.01); // float above the plane
            group.add(textMesh);
        }
    }

    // --- Billboard behaviour (always face camera) ---
    group.userData.handlers = {
        update: (camera) => {
            group.lookAt(camera.position);
        }
    };

    // --- Cleanup resource allocation ---
    group.userData.cleanup = () => {
        geo.dispose();
        mat.dispose();
        if (texUniform.value) {
            texUniform.value.dispose();
        }
        if (textMesh && textMesh.parent === group) {
            group.remove(textMesh);
            if (textMesh.geometry) textMesh.geometry.dispose();
            if (textMesh.material) textMesh.material.dispose();
        }
        // kill any GSAP timelines (none used, but safe)
    };

    return group;
}
